  31 /**
  32  * Retrieve relevant context for a query using RAG
  33  */
  34 export async function retrieveContext(
  35   query: string,
  36   options: RetrievalOptions = {}
  37 ): Promise<RetrievalResult> {
  38   const {
  39     topK = 5,
  40     minScore = 0.5,
  41     projectId,
  42     userId,
  43     includeTypes,
  44   } = options;
  45 
  46   try {
  47     const { useCache = true, rerank = false, rerankStrategy = 'hybrid' } = options;
  48 
  49     // Check cache first
  50     if (useCache) {
  51       const { getCacheManager } = await import('./cache');
  52       const cache = getCacheManager().getSearchCache();
  53       const cached = cache.getResults(query, { projectId, topK, minScore });
  54       
  55       if (cached) {
  56         return cached;
  57       }
  58     }
  59 
  60     // 1. Generate embedding for the query (with caching)
  61     const queryEmbedding = await generateEmbedding(query, useCache);
  62 
  63     // 2. Search vector store for similar chunks
  64     const vectorStore = getVectorStore();
  65     
  66     // Load project chunks if projectId is provided
  67     if (projectId) {
  68       await vectorStore.loadProjectChunks(projectId);
  69     }
  70 
  71     let searchResults = await vectorStore.search(queryEmbedding, {
  72       topK: rerank ? topK * 2 : topK, // Get more results if reranking
  73       minScore,
  74       filter: {
  75         projectId,
  76         userId,
  77         type: includeTypes?.[0], // Simple filter for now
  78       },
  79     });
  80 
  81     // 2.5. Apply reranking if enabled
  82     if (rerank && searchResults.length > 0) {
  83       const { getReranker } = await import('./reranker');
  84       const reranker = getReranker();
  85       searchResults = await reranker.rerank(query, searchResults, {
  86         strategy: rerankStrategy,
  87         topK,
  88       });
  89     }
  90 
  91     // 3. Format results
  92     const sources = searchResults.map(result => ({
  93       content: result.chunk.content,
  94       score: result.score,
