 146  */
 147 export async function retrieveContextEnhanced(
 148   query: string,
 149   options: RetrievalOptions = {}
 150 ): Promise<RetrievalResult> {
 151   // Generate query variations
 152   const queries = [
 153     query,
 154     // Add simple variations
 155     `What is ${query}?`,
 156     `Explain ${query}`,
 157   ];
 158 
 159   // Retrieve for all variations
 160   const results = await retrieveContextBatch(queries, {
 161     ...options,
 162     topK: Math.ceil((options.topK || 5) / queries.length),
 163   });
 164 
 165   // Merge and deduplicate results
 166   const allSources = results.flatMap(r => r.sources);
 167   const uniqueSources = Array.from(
 168     new Map(allSources.map(s => [s.content, s])).values()
 169   )
 170     .sort((a, b) => b.score - a.score)
 171     .slice(0, options.topK || 5);
 172 
 173   const context = uniqueSources
 174     .map((source, idx) => {
 175       return `[Context ${idx + 1}] (Relevance: ${(source.score * 100).toFixed(1)}%, Source: ${source.sourceFile || 'Unknown'})\n${source.content}`;
 176     })
 177     .join('\n\n---\n\n');
 178 
 179   return {
 180     context,
 181     sources: uniqueSources,
 182   };
 183 }
